:["score","scale_min","scale_max","summary"],"properties":{"score":{"type":"number","minimum":0,"maximum":10},"scale_min":{"type":"number","const":0},"scale_max":{"type":"number","const":10},"summary":{"type":"string","minLength":1,"pattern":"\\\\S"},"subscores":{"type":"object","additionalProperties":{"type":"number","minimum":0,"maximum":10}}}},"particularly_suitable":{"type":["boolean","null"]},"data":{"type":"object","properties":{"research_methods":{"type":"array","items":{"type":"string"}},"teaching_load":{"type":["string","object","null"],"properties":{"status":{"type":"string"},"details":{"type":"string"}}},"url_roles":{"type":"object","additionalProperties":false,"properties":{"official_url":{"type":"string","enum":["vacancy","listing","application_portal","context","unknown"]},"source_url":{"type":"string","enum":["vacancy","listing","application_portal","context","unknown"]},"application_url":{"type":"string","enum":["vacancy","listing","application_portal","context","unknown"]}}}}},"last_checked_at":{"type":"string","format":"date-time"},"sources":{"type":"array","minItems":1,"items":{"type":"object","required":["url","kind","checked_at","supports"],"properties":{"url":{"type":"string","pattern":"^https?://[^\\\\s]+$"},"kind":{"type":"string","enum":["official","official_listing","institution","graduate_school","discovery","unknown"]},"checked_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"string","format":"date"}]},"supports":{"type":"array","items":{"type":"string"}},"unmapped_supports":{"type":"array","items":{"type":"string"}},"legacy":{"type":"object"}}}}}}'::jsonb then
